use std::fmt::Write;

use super::{
    plan::{
        ColumnPlan, ColumnSource, Presence, ProtoField, RelationPlan, RelationSource,
        RelationalPlan, ScalarType, ScalarValue,
    },
    prost_binding::ProstBindings,
};

pub(super) fn render(plan: &RelationalPlan, bindings: &ProstBindings) -> String {
    let mut output = String::new();
    writeln!(
        output,
        "// @generated by protobuf_source_codegen; do not edit.\n"
    )
    .expect("writing generated Rust to String cannot fail");

    render_enum_symbol_constants(&mut output, plan);
    render_capture_constructor(&mut output, plan);
    for root in &plan.roots {
        let root_type = bindings.root_type(root.spec_index);
        writeln!(
            output,
            "pub(crate) fn append_{}_root(\n    capture: &mut crate::protobuf_source::SourceTableCapture,\n    parent_row_id: u64,\n    value: &{},\n) -> anyhow::Result<()> {{",
            root.root_table_name, root_type
        )
        .expect("writing generated Rust to String cannot fail");
        let mut renderer = EmitterRenderer {
            output: &mut output,
            plan,
            bindings,
            indent: 1,
        };
        renderer.line("let _ = value;");
        renderer.emit_relation(root.relation_slot, "value", "parent_row_id", None);
        renderer.line("Ok(())");
        writeln!(output, "}}\n").expect("writing generated Rust to String cannot fail");
    }
    output
}

fn render_enum_symbol_constants(output: &mut String, plan: &RelationalPlan) {
    for (origin_index, origin) in plan.enum_origins.iter().enumerate() {
        writeln!(
            output,
            "const PROTOBUF_ENUM_SYMBOLS_{origin_index}: &[crate::protobuf_source::EnumSymbol] = &["
        )
        .expect("writing generated Rust to String cannot fail");
        for symbol in &origin.symbols {
            writeln!(
                output,
                "    crate::protobuf_source::EnumSymbol::new({}, {}),",
                symbol.number,
                literal(&symbol.symbol)
            )
            .expect("writing generated Rust to String cannot fail");
        }
        writeln!(output, "];\n").expect("writing generated Rust to String cannot fail");
    }
}

fn render_capture_constructor(output: &mut String, plan: &RelationalPlan) {
    writeln!(
        output,
        "pub(crate) fn new_protobuf_source_capture(\n    options: crate::protobuf_source::SpoolOptions,\n) -> anyhow::Result<crate::protobuf_source::SourceTableCapture> {{"
    )
    .expect("writing generated Rust to String cannot fail");
    writeln!(output, "    let relations = vec![")
        .expect("writing generated Rust to String cannot fail");
    for relation in &plan.relations {
        writeln!(
            output,
            "        crate::protobuf_source::RelationSpec::new({}, std::sync::Arc::new(arrow_schema::Schema::new(vec![",
            literal(&relation.name)
        )
        .expect("writing generated Rust to String cannot fail");
        for column in &relation.columns {
            writeln!(output, "            {},", render_arrow_field(column))
                .expect("writing generated Rust to String cannot fail");
        }
        writeln!(output, "        ]))),").expect("writing generated Rust to String cannot fail");
    }
    writeln!(output, "    ];").expect("writing generated Rust to String cannot fail");
    writeln!(output, "    let enum_origins = vec![")
        .expect("writing generated Rust to String cannot fail");
    for (origin_index, origin) in plan.enum_origins.iter().enumerate() {
        writeln!(
            output,
            "        crate::protobuf_source::EnumOriginSpec::new(crate::protobuf_source::RelationSlot::new({}), {}, {}, PROTOBUF_ENUM_SYMBOLS_{}),",
            origin.relation_slot,
            literal(&origin.field_path),
            literal(&origin.enum_fqn),
            origin_index
        )
        .expect("writing generated Rust to String cannot fail");
    }
    writeln!(output, "    ];").expect("writing generated Rust to String cannot fail");
    writeln!(
        output,
        "    crate::protobuf_source::SourceTableCapture::new(relations, enum_origins, options)\n}}\n"
    )
    .expect("writing generated Rust to String cannot fail");
}

fn render_arrow_field(column: &ColumnPlan) -> String {
    format!(
        "arrow_schema::Field::new({}, {}, {})",
        literal(&column.name),
        render_arrow_type(column),
        column.nullable
    )
}

fn render_arrow_type(column: &ColumnPlan) -> String {
    match &column.source {
        ColumnSource::RowId | ColumnSource::ParentRowId | ColumnSource::RepeatedIndex => {
            "arrow_schema::DataType::UInt64".to_string()
        }
        ColumnSource::Scalar { scalar, .. } => match scalar {
            ScalarType::Boolean => "arrow_schema::DataType::Boolean",
            ScalarType::Int32 => "arrow_schema::DataType::Int32",
            ScalarType::Int64 => "arrow_schema::DataType::Int64",
            ScalarType::UInt32 => "arrow_schema::DataType::UInt32",
            ScalarType::UInt64 => "arrow_schema::DataType::UInt64",
            ScalarType::Float32 => "arrow_schema::DataType::Float32",
            ScalarType::Float64 => "arrow_schema::DataType::Float64",
            ScalarType::Utf8 => "arrow_schema::DataType::Utf8",
            ScalarType::Binary => "arrow_schema::DataType::Binary",
        }
        .to_string(),
        ColumnSource::Struct { fields, .. } => {
            let fields = fields
                .iter()
                .map(render_arrow_field)
                .collect::<Vec<_>>()
                .join(", ");
            format!("arrow_schema::DataType::Struct(vec![{fields}].into())")
        }
    }
}

struct EmitterRenderer<'a> {
    output: &'a mut String,
    plan: &'a RelationalPlan,
    bindings: &'a ProstBindings,
    indent: usize,
}

impl EmitterRenderer<'_> {
    fn emit_relation(
        &mut self,
        relation_slot: usize,
        value: &str,
        parent_row_id: &str,
        repeated_index: Option<&str>,
    ) {
        let relation = &self.plan.relations[relation_slot];
        let has_row_id = relation
            .columns
            .iter()
            .any(|column| matches!(column.source, ColumnSource::RowId));
        let row_id = format!("row_id_{relation_slot}");
        if has_row_id {
            self.line(&format!(
                "let {row_id} = capture.allocate_row_id(crate::protobuf_source::RelationSlot::new({relation_slot}))?;"
            ));
        }
        self.line(&format!(
            "capture.append_row(crate::protobuf_source::RelationSlot::new({relation_slot}), |row| {{"
        ));
        self.indent += 1;
        for (column_slot, column) in relation.columns.iter().enumerate() {
            self.emit_column(
                column,
                column_slot,
                value,
                parent_row_id,
                repeated_index,
                has_row_id.then_some(row_id.as_str()),
            );
        }
        self.line("Ok(())");
        self.indent -= 1;
        self.line("})?;");

        for child in self.child_relations(relation_slot) {
            self.emit_child(child, value, has_row_id.then_some(row_id.as_str()));
        }
    }

    fn emit_child(
        &mut self,
        relation: RelationPlan,
        parent_value: &str,
        parent_row_id: Option<&str>,
    ) {
        let parent_row_id = parent_row_id.expect("a relation with children has a planned row id");
        let slot = relation.slot;
        match &relation.source {
            RelationSource::RepeatedMessage { field, .. }
            | RelationSource::RepeatedValue { field, .. } => {
                let binding = self.bindings.field(field);
                let index = format!("repeated_index_{slot}");
                let value = format!("value_{slot}");
                self.line(&format!(
                    "for ({index}, {value}) in {parent_value}.{}.iter().enumerate() {{",
                    binding.rust_field_ident
                ));
                self.indent += 1;
                self.line(&format!(
                    "let {index} = u64::try_from({index}).map_err(|_| anyhow::anyhow!({}))?;",
                    literal(&format!(
                        "repeated index overflows u64 in relation {}",
                        relation.name
                    ))
                ));
                self.emit_relation(slot, &value, parent_row_id, Some(&index));
                self.indent -= 1;
                self.line("}");
            }
            RelationSource::OptionalMessage { field, .. } => {
                let binding = self.bindings.field(field);
                let value = format!("value_{slot}");
                self.line(&format!(
                    "if let Some({value}) = {parent_value}.{}.as_ref() {{",
                    binding.rust_field_ident
                ));
                self.indent += 1;
                self.emit_relation(slot, &value, parent_row_id, None);
                self.indent -= 1;
                self.line("}");
            }
            RelationSource::OneofMessage { field, .. } => {
                let binding = self.bindings.field(field);
                let oneof = binding
                    .oneof
                    .as_ref()
                    .expect("oneof relation has a oneof prost binding");
                let value = format!("value_{slot}");
                self.line(&format!(
                    "if let Some({}::{}({value})) = {parent_value}.{}.as_ref() {{",
                    oneof.rust_enum_path, oneof.rust_variant_ident, oneof.rust_group_ident
                ));
                self.indent += 1;
                self.emit_relation(slot, &value, parent_row_id, None);
                self.indent -= 1;
                self.line("}");
            }
            RelationSource::Root { .. } => unreachable!("a root relation is not a child"),
        }
    }

    #[allow(clippy::too_many_arguments)]
    fn emit_column(
        &mut self,
        column: &ColumnPlan,
        slot: usize,
        value: &str,
        parent_row_id: &str,
        repeated_index: Option<&str>,
        row_id: Option<&str>,
    ) {
        match &column.source {
            ColumnSource::RowId => self.emit_typed("u64", slot, row_id.expect("planned row id")),
            ColumnSource::ParentRowId => self.emit_typed("u64", slot, parent_row_id),
            ColumnSource::RepeatedIndex => {
                self.emit_typed("u64", slot, repeated_index.expect("planned repeated index"));
            }
            ColumnSource::Scalar {
                scalar,
                value: source,
            } => match source {
                ScalarValue::RelationValue => {
                    self.emit_scalar_value(*scalar, slot, ScalarExpression::Borrowed(value))
                }
                ScalarValue::Field(field) => {
                    self.emit_field_value(*scalar, slot, value, field);
                }
            },
            ColumnSource::Struct { field, fields } => {
                let binding = self.bindings.field(field);
                let nested_value = format!("struct_value_{}_{}", field.number, slot);
                self.line(&format!(
                    "row.struct_(crate::protobuf_source::ColumnSlot::new({slot}), {value}.{}.is_some(), |row| {{",
                    binding.rust_field_ident
                ));
                self.indent += 1;
                self.line(&format!(
                    "let {nested_value} = {value}.{}.as_ref().expect(\"Struct closure is called only for a present message\");",
                    binding.rust_field_ident
                ));
                for (nested_slot, nested) in fields.iter().enumerate() {
                    self.emit_column(nested, nested_slot, &nested_value, "", None, None);
                }
                self.line("Ok(())");
                self.indent -= 1;
                self.line("})?;");
            }
        }
    }

    fn emit_field_value(
        &mut self,
        scalar: ScalarType,
        slot: usize,
        containing_value: &str,
        field: &ProtoField,
    ) {
        let binding = self.bindings.field(field);
        match (&field.presence, &binding.oneof) {
            (Presence::Oneof { .. }, Some(oneof)) => {
                let field_value = format!("field_value_{}_{}", field.number, slot);
                self.line(&format!(
                    "if let Some({}::{}({field_value})) = {containing_value}.{}.as_ref() {{",
                    oneof.rust_enum_path, oneof.rust_variant_ident, oneof.rust_group_ident
                ));
                self.indent += 1;
                self.emit_scalar_value(scalar, slot, ScalarExpression::Borrowed(&field_value));
                self.indent -= 1;
                self.line("} else {");
                self.indent += 1;
                self.emit_null(slot);
                self.indent -= 1;
                self.line("}");
            }
            (Presence::Explicit, None) => {
                let field_value = format!("field_value_{}_{}", field.number, slot);
                self.line(&format!(
                    "if let Some({field_value}) = {containing_value}.{}.as_ref() {{",
                    binding.rust_field_ident
                ));
                self.indent += 1;
                self.emit_scalar_value(scalar, slot, ScalarExpression::Borrowed(&field_value));
                self.indent -= 1;
                self.line("} else {");
                self.indent += 1;
                self.emit_null(slot);
                self.indent -= 1;
                self.line("}");
            }
            (Presence::Implicit, None) => {
                let expression = format!("{containing_value}.{}", binding.rust_field_ident);
                self.emit_scalar_value(scalar, slot, ScalarExpression::Direct(&expression));
            }
            _ => unreachable!("planner and prost binding disagree about field presence"),
        }
    }

    fn emit_scalar_value(
        &mut self,
        scalar: ScalarType,
        slot: usize,
        expression: ScalarExpression<'_>,
    ) {
        let value = expression.value();
        match scalar {
            ScalarType::Boolean => self.emit_typed("bool", slot, &expression.copy_value()),
            ScalarType::Int32 => self.emit_typed("i32", slot, &expression.copy_value()),
            ScalarType::Int64 => self.emit_typed("i64", slot, &expression.copy_value()),
            ScalarType::UInt32 => self.emit_typed("u32", slot, &expression.copy_value()),
            ScalarType::UInt64 => self.emit_typed("u64", slot, &expression.copy_value()),
            ScalarType::Float32 => self.emit_typed("f32", slot, &expression.copy_value()),
            ScalarType::Float64 => self.emit_typed("f64", slot, &expression.copy_value()),
            ScalarType::Utf8 => self.emit_typed("utf8", slot, &format!("({value}).as_str()")),
            ScalarType::Binary => self.emit_typed("binary", slot, &format!("({value}).as_slice()")),
        }
    }

    fn emit_typed(&mut self, method: &str, slot: usize, value: &str) {
        self.line(&format!(
            "row.{method}(crate::protobuf_source::ColumnSlot::new({slot}), {value})?;"
        ));
    }

    fn emit_null(&mut self, slot: usize) {
        self.line(&format!(
            "row.null(crate::protobuf_source::ColumnSlot::new({slot}))?;"
        ));
    }

    fn child_relations(&self, parent: usize) -> Vec<RelationPlan> {
        self.plan
            .relations
            .iter()
            .filter(|relation| relation.source.parent() == Some(parent))
            .cloned()
            .collect()
    }

    fn line(&mut self, line: &str) {
        writeln!(self.output, "{}{}", "    ".repeat(self.indent), line)
            .expect("writing generated Rust to String cannot fail");
    }
}

#[derive(Clone, Copy)]
enum ScalarExpression<'a> {
    Direct(&'a str),
    Borrowed(&'a str),
}

impl<'a> ScalarExpression<'a> {
    fn value(self) -> &'a str {
        match self {
            Self::Direct(value) | Self::Borrowed(value) => value,
        }
    }

    fn copy_value(self) -> String {
        match self {
            Self::Direct(value) => value.to_string(),
            Self::Borrowed(value) => format!("*({value})"),
        }
    }
}

fn literal(value: &str) -> String {
    format!("{value:?}")
}
